import React from "react";

const Snake = ({ snake }) => {
  return (
    <>
      {snake.map((segment, index) => {
        const isHead = index === snake.length - 1;
        return (
          <div
            key={index}
            className={`snake-segment ${isHead ? "snake-head" : ""}`}
            style={{
              gridRowStart: segment[1] + 1,
              gridColumnStart: segment[0] + 1,
              backgroundColor: isHead ? "darkgreen" : "green",
            }}
          ></div>
        );
      })}
    </>
  );
};

export default Snake;
